/// Get valid targets for a single mode requirement, unwrapping UpToTargets.
fn valid_targets_for_mode(
    state: &GameState,
    caster: PlayerId,
    spell_id: ObjectId,
    mode_req: &crate::cards::TargetRequirement,
    behavior: &dyn crate::cards::CardBehavior,
