            let mut actions = Vec::new();
            for t1 in &targets1 {
                for t2 in &targets2 {
                    if t1 != t2 {
                        let pair: Vec<crate::actions::Target> = vec![t1.clone(), t2.clone()];
                        actions.push(Action::CastSpell {
                            object_id: spell_id,
                            targets: pair,
                            sacrifice: None, exile_count: None, alternative_cost: None,
                        });
                    }
                }
            }
            actions
        }
