                            combo.insert(0, targets[i].clone());
                            result.push(combo);
                        }
                    }
                    result
                }
                for combo in target_combinations(&options, k) {
                    actions.push(Action::CastSpell {
                        object_id: spell_id,
                        targets: combo,
                        sacrifice: None, exile_count: None, alternative_cost: None,
                    });
                }
            }
            actions
        }
    }
